import { provisionTrackingNumber } from '@projexlight/connector-twilio-voice';

const number = await provisionTrackingNumber({
  install_id: install.install_id,
  tenant_id: tenant.tenant_id,
  phone_number: '',        // let the provider mint one
  area_code: '415',
  friendly_name: 'West Coast Sales',
  purpose: 'sales-outbound',
  assigned_persona_id: null,
});
console.log(number.phone_number, number.status); // e.g. '+1415...' 'active'

import { placeCall } from '@projexlight/connector-twilio-voice';

const call = await placeCall({
  install_id: install.install_id,
  tenant_id: tenant.tenant_id,
  to_number: '+14155550123',
  from_number: null,           // fall back to the tenant's active tracking number
  record: true,                // honoured only if consent resolves to 'granted'
  machine_detection: true,
});
console.log(call.status, call.recording_withheld_reason);

import { verifyTwilioSignature, applyStatusCallback, normalizeAnsweredBy } from '@projexlight/connector-twilio-voice';

const params = { CallSid: 'CA123', CallStatus: 'completed', AnsweredBy: 'machine_start' };
const check = verifyTwilioSignature('https://cloud.projexlight.com/api/voice/webhooks/twilio/status', params, req.headers['x-twilio-signature']);
if (check.enforced && !check.verified) throw new Error('InvalidSignature');
const result = await applyStatusCallback(params);
console.log(result.matched, result.call?.is_voicemail, normalizeAnsweredBy('machine_start'));
